<script setup>
import {onMounted,ref} from 'vue';import request from '../api/request';const list=ref([]);const filter=ref(0);const msg=ref('');async function load(){const r=await request.get('/admin/reviews',{params:{status:filter.value||undefined}});list.value=r.data.data||[]}async function audit(id,status){await request.put(`/admin/reviews/${id}/audit`,null,{params:{status}});msg.value='审核完成';await load()}onMounted(load)
</script>
<template><main class="page-shell"><header class="page-heading"><div><div class="section-kicker">MODERATION</div><h1>评论审核</h1><p>审核通过后评论才会在商品详情页公开展示。</p></div><select v-model="filter" @change="load"><option :value="0">全部</option><option :value="1">已通过</option><option :value="2">已拒绝</option></select></header><p v-if="msg" class="notice success">{{msg}}</p><section class="admin-table-card table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>商品</th><th>用户</th><th>评分</th><th>内容</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in list" :key="r.id"><td>{{r.id}}</td><td>{{r.productId}}</td><td>{{r.userId}}</td><td>{{r.rating}}</td><td>{{r.content}}</td><td>{{r.auditStatus===1?'通过':r.auditStatus===2?'拒绝':'待审核'}}</td><td><button class="primary-button" @click="audit(r.id,1)">通过</button> <button class="danger-button" @click="audit(r.id,2)">拒绝</button></td></tr></tbody></table></section></main></template>
